export async function gate({ referenceDir, submissionDir }) {
  const cookie = crypto.randomBytes(32).toString('hex');
  const runnerPath = path.join(referenceDir, '_runner.mjs');
  const resultPath = path.join(referenceDir, '_result.json');
  const submissionPath = path.join(submissionDir, 'answer.mjs');
  const pinnedPath = path.join(referenceDir, 'pinned-test-cases.txt');

  const runnerSrc = [
    "import fs from 'node:fs';",
    "import assert from 'node:assert/strict';",
    "import { pathToFileURL } from 'node:url';",
    'const resultPath = ' + JSON.stringify(resultPath) + ';',
    'const submissionPath = ' + JSON.stringify(submissionPath) + ';',
    'const pinnedPath = ' + JSON.stringify(pinnedPath) + ';',
    'const cookie = ' + JSON.stringify(cookie) + ';',
    'function finish(payload) { try { fs.writeFileSync(resultPath, JSON.stringify(payload)); } catch (e) {} }',
    'const realExit = process.exit.bind(process);',
    "process.exit = (code) => { finish({ ok: false, reason: 'early_exit', code: (code == null ? 0 : code), cookie: null }); realExit(code == null ? 0 : code); };",
    'let passed = 0;',
    'const failures = [];',
    'function test(name, fn) { try { fn(); passed++; } catch (err) { failures.push(String(name) + ": " + (err && err.message ? err.message : String(err))); } }',
    'try {',
    '  const mod = await import(pathToFileURL(submissionPath).href);',
    '  const dedupeSorted = mod.dedupeSorted;',
    "  if (typeof dedupeSorted !== 'function') { finish({ ok: false, reason: 'dedupeSorted not exported as function', cookie: cookie, passed: 0 }); } else {",
    '    let pinned = "";',
    '    try { pinned = fs.readFileSync(pinnedPath, "utf8"); } catch (e) { pinned = ""; }',
    '    if (pinned && pinned.trim()) {',
    '      try { const runPinned = new Function("test", "assert", "dedupeSorted", pinned); runPinned(test, assert, dedupeSorted); } catch (err) { failures.push("pinned-suite: " + (err && err.message ? err.message : String(err))); }',
    '    } else {',
    '      test("empty array", () => { assert.deepStrictEqual(dedupeSorted([]), []); });',
    '      test("single element", () => { assert.deepStrictEqual(dedupeSorted([5]), [5]); });',
    '      test("no duplicates", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]); });',
    '      test("all duplicates", () => { assert.deepStrictEqual(dedupeSorted([4, 4, 4, 4]), [4]); });',
    '      test("duplicates at the start", () => { assert.deepStrictEqual(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]); });',
    '      test("duplicates at the end", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]); });',
    '      test("negative numbers with duplicates", () => { assert.deepStrictEqual(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]); });',
    '      test("randomized property check against a reference oracle", () => {',
    '        for (let trial = 0; trial < 20; trial++) {',
    '          const len = 1 + Math.floor(Math.random() * 10);',
    '          const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);',
    '          const expected = [...new Set(arr)];',
    '          assert.deepStrictEqual(dedupeSorted(arr), expected);',
    '        }',
    '      });',
    '    }',
    '    test("wider range property", () => {',
    '      for (let trial = 0; trial < 30; trial++) {',
    '        const len = Math.floor(Math.random() * 40);',
    '        const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 1001) - 500).sort((a, b) => a - b);',
    '        const expected = [...new Set(arr)];',
    '        assert.deepStrictEqual(dedupeSorted(arr), expected);',
    '      }',
    '    });',
    '    const ok = failures.length === 0 && passed >= 8;',
    '    finish({ ok: ok, passed: passed, failures: failures, cookie: cookie });',
    '  }',
    '} catch (err) { finish({ ok: false, reason: String(err && err.stack ? err.stack : err), cookie: cookie, passed: passed }); }',
  ].join('\n');

  fs.writeFileSync(runnerPath, runnerSrc, 'utf8');
  try { fs.unlinkSync(resultPath); } catch (e) {}

  const outcome = await new Promise((resolve) => {
    const child = spawn(process.execPath, [runnerPath], {
      stdio: ['ignore', 'pipe', 'pipe'],
      cwd: referenceDir,
    });
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      try { child.kill('SIGKILL'); } catch (e) {}
      resolve({ timeout: true });
    }, 12000);
    child.on('close', () => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({ timeout: false });
    });
    child.on('error', () => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({ timeout: false, error: true });
    });
  });

  if (outcome.timeout) {
    return { accept: false, reason: 'test suite timed out (did not run to completion)' };
  }
  if (!fs.existsSync(resultPath)) {
    return { accept: false, reason: 'test suite did not complete; no result written' };
  }
  let result;
  try {
    result = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
  } catch (e) {
    return { accept: false, reason: 'unreadable result file' };
  }
  if (result.cookie !== cookie) {
    return { accept: false, reason: 'result cookie mismatch; suite completion not established' };
  }
  if (!result.ok) {
    const detail = (result.failures && result.failures.length)
      ? result.failures.join('; ')
      : (result.reason || 'tests failed');
    return { accept: false, reason: detail };
  }
  return { accept: true, reason: 'all ' + result.passed + ' tests passed' };
}
